 1→/**
 2→ * @cipherbox/crypto - Vault IPNS Key Derivation
 3→ *
 4→ * Derives a deterministic Ed25519 IPNS keypair for the user's vault
 5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
 6→ *
 7→ * Derivation path:
 8→ *   secp256k1 privateKey (32 bytes)
 9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-vault-ipns-v1")
10→ *     -> 32-byte Ed25519 seed
11→ *     -> Ed25519 keypair
12→ *     -> IPNS name (k51...)
13→ *
14→ * This enables self-sovereign vault recovery: recovery phrase -> privateKey
15→ * -> derive vault IPNS key -> resolve IPNS -> decrypt vault.
16→ *
17→ * Domain separation: Uses "cipherbox-vault-ipns-v1" info (different from
18→ * registry's "cipherbox-device-registry-ipns-v1"), ensuring the same
19→ * privateKey produces different IPNS keypairs for vault vs registry.
20→ */
21→
22→import { deriveKey } from '../keys/derive';
23→import * as ed from '@noble/ed25519';
24→import { deriveIpnsName } from '../ipns/derive-name';
25→import { CryptoError } from '../types';
26→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
27→
28→const VAULT_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
29→const VAULT_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-ipns-v1');
30→
31→/**
32→ * Derive the deterministic Ed25519 IPNS keypair for the user's vault.
33→ *
34→ * Given the same secp256k1 privateKey, this always produces the same
35→ * IPNS name, enabling vault discovery from any device with the user's key.
36→ *
37→ * @param userPrivateKey - 32-byte secp256k1 private key
38→ * @returns Ed25519 keypair and IPNS name for the vault
39→ * @throws CryptoError if the private key is not 32 bytes
40→ */
41→export async function deriveVaultIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
42→  privateKey: Uint8Array;
43→  publicKey: Uint8Array;
44→  ipnsName: string;
45→}> {
46→  // Validate input key length
47→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
48→    throw new CryptoError('Invalid private key size for vault derivation', 'INVALID_KEY_SIZE');
49→  }
50→
51→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
52→  const ed25519Seed = await deriveKey({
53→    inputKey: userPrivateKey,
54→    salt: VAULT_HKDF_SALT,
55→    info: VAULT_HKDF_INFO,
56→    outputLength: 32,
57→  });
58→
59→  // 2. Derive Ed25519 public key from seed (deterministic)
60→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
61→
62→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
63→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
64→
65→  return {
66→    privateKey: ed25519Seed,
67→    publicKey: ed25519PublicKey,
68→    ipnsName,
69→  };
70→}
71→

